/* ---------- more lessons, grade 5 English, science and social studies ---------- */
LESSONS5X.push(
 {id:'g5_words_figurative',gen:'words5',isl:'words',types:[],title:'Figurative language',
  build(){return [
   teachCard('Not word for word',`<p><b>Simile:</b> compares with like or as. "Fast <b>as</b> a cheetah."</p><p><b>Metaphor:</b> says one thing <b>is</b> another. "The room was an oven."</p><p><b>Personification:</b> gives human actions to things. "The wind whispered."</p><p><b>Hyperbole:</b> a huge exaggeration. "I've told you a million times!"</p>`,'Let\'s try one!'),
   guided(`<i>"The stars danced in the sky."</i> Which kind?`,strChoices('personification',['simile','hyperbole']),`Can stars really dance?`,`Stars doing a human action: <b>personification</b>.`),
   guided(`<i>"Her smile was as bright as the sun."</i> Which kind?`,strChoices('simile',['metaphor','hyperbole']),`Look for like or as.`,`It uses <b>as</b>: a simile.`)]},
  get practice(){return tagIdx5('words5','figurative')}},
 {id:'g5_gram_commas',gen:'grammar5',isl:'grammar',types:[],title:'Commas that help readers',
  build(){return [
   teachCard('Four comma jobs',`<p>1. In a <b>list</b>: apples, pears and plums.</p><p>2. After an <b>introductory word or phrase</b>: Yes, I can. After lunch, we read.</p><p>3. To set off a <b>name</b>: Sam, come here.</p><p>4. Before a <b>tag question</b>: It's late, isn't it?</p>`,'Let\'s try one!'),
   guided(`Where does the comma go? <i>"Well I think we should go."</i>`,strChoices('after Well',['after think','after should']),`Well is an introductory word.`,`<b>Well,</b> I think we should go.`)]},
  get practice(){return tagIdx5('grammar5','commas')}},
 {id:'g5_sci_foodweb',gen:'science5',isl:'science',types:[],title:'Food webs: where energy goes',
  build(){return [
   teachCard('From the sun to you',`<p><b>Producers</b> (plants) use sunlight to make food.</p><p><b>Consumers</b> eat plants or other animals: a rabbit eats grass, a fox eats the rabbit.</p><p><b>Decomposers</b> (mushrooms, worms, bacteria) break down dead things and return nutrients to the soil.</p><p>Every arrow in a food web shows where the <b>energy goes</b>.</p>`,'Let\'s try one!'),
   guided(`Grass → rabbit → fox. Where did the fox\'s energy first come from?`,strChoices('the sun',['the rabbit\'s fur','the soil']),`Follow it back to the grass.`,`It started as <b>sunlight</b>.`),
   guided(`Which is a decomposer?`,strChoices('a worm',['a hawk','a tree']),`It breaks down dead things.`,`A <b>worm</b>.`)]},
  get practice(){return tagIdx5('science5','foodweb')}},
 {id:'g5_hist_constitution',gen:'history5',isl:'history',types:[],title:'The Constitution and its branches',
  build(){return [
   teachCard('Three branches, one government',`<p>The <b>Constitution</b> (1787) set up the U.S. government.</p><p><b>Legislative</b> (Congress) makes laws. <b>Executive</b> (the President) carries them out. <b>Judicial</b> (the courts) decides what laws mean.</p><p><b>Checks and balances</b> let each branch limit the others. The <b>Bill of Rights</b> protects freedoms like speech and religion.</p>`,'Let\'s try one!'),
   guided(`Which branch makes laws?`,strChoices('legislative',['executive','judicial']),`Congress.`,`The <b>legislative</b> branch.`),
   guided(`Why have checks and balances?`,strChoices('so no branch gets too much power',['so laws never change','so taxes go up']),`Each branch limits the others.`,`So <b>no branch gets too much power</b>.`)]},
  get practice(){return tagIdx5('history5','constitution')}}
);

/* ---------- Science Springs, grade 5: generated questions with data, diagrams and sorting (NGSS 5) ---------- */
BANKX.science5=[
 {tag:'matter',f(){const M=[['ice cube','s'],['rock','s'],['pencil','s'],['milk','l'],['juice','l'],['rain','l'],['steam','g'],['air in a balloon','g'],['oxygen','g']],it=['s','l','g'].flatMap(b=>sxPick(M.filter(x=>x[1]===b),2));
  return sxSort('Sort each kind of matter: <b>solid</b>, <b>liquid</b> or <b>gas</b>?',[['s','Solid'],['l','Liquid'],['g','Gas']],it,'Solids keep their shape. Liquids take the shape of their container. Gases spread out to fill any space.','All three are matter made of tiny particles; they are packed differently.')}},
 {tag:'matter',f(){const w=R(180,260),salt=R(15,40);
  return {prompt:`Pip dissolved salt in water and left the dish in the sun. What does the table show?`,visual:sxTable(['Day','1','2','3','4'],[['Mass in dish (g)',w+salt,Math.round((w*2)/3)+salt,Math.round(w/3)+salt,salt]]),...strChoices(`The water evaporated, but the salt particles were there all along: ${salt} g of salt is left.`,['The salt disappeared when it dissolved.','The salt turned into water.','The mass stayed the same every day.']),long:true,hint:`What is left on Day 4?`,explain:`Only the water left as gas. <b>${salt} g of salt</b> remains, so the salt was in the water as particles too small to see.`}}},
 {tag:'conserve',f(){const a=R(40,200),b=R(20,150),k=R(0,2),[pr,ex]=[[`Pip pours <b>${a} g</b> of water into a cup and stirs in <b>${b} g</b> of sugar until it dissolves. What is the total mass?`,`Dissolving does not destroy matter: ${a} + ${b} = <b>${a+b} g</b>.`],[`In a sealed bag, <b>${a} g</b> of vinegar and <b>${b} g</b> of baking soda mix and make gas. What is the mass of the sealed bag's contents now?`,`Nothing left the sealed bag: ${a} + ${b} = <b>${a+b} g</b>.`],[`A <b>${a} g</b> ice cube melts in a <b>${b} g</b> cup. What is the mass of the cup and water?`,`Melting does not change mass: ${a} + ${b} = <b>${a+b} g</b>.`]][k];
  return {prompt:pr,unit:'g',...numChoices(a+b,[Math.abs(a-b)||a+b+5,a,a+b+10,b]),hint:`Matter is not created or destroyed when it changes or mixes.`,explain:ex}}},
 {tag:'conserve',f(){const m=R(20,90)*5;
  return {prompt:`Pip weighed ice before and after it melted in a closed jar.`,visual:sciBars(['Before (ice)','After (water)'],[m,m],'Mass (g)','','#5fc3f0'),...strChoices('The mass stayed the same when the ice melted.',['Water is heavier than ice.','The ice lost mass when it melted.','Melting creates new matter.']),long:true,hint:`Compare the two bars.`,explain:`Both are ${m} g: <b>mass is conserved</b> when matter changes state.`}}},
 {tag:'props',f(){const M=[['copper wire','c'],['aluminum foil','c'],['steel key','c'],['iron nail','c'],['rubber band','i'],['plastic spoon','i'],['wooden stick','i'],['glass rod','i']],it=sxPick(M.slice(0,4),3).concat(sxPick(M.slice(4),3));
  return sxSort('Sort the materials: does electricity flow through them?',[['c','Conductor'],['i','Insulator']],it,'Metals are usually good conductors.','Metals conduct electricity; rubber, plastic, wood and glass are insulators.')}},
 {tag:'props',f(){const S=[['sugar','yes'],['salt','yes'],['drink powder','yes'],['sand','no'],['pebbles','no'],['cooking oil','no'],['chalk dust','no']],it=sxPick(S.slice(0,3),3).concat(sxPick(S.slice(3),3));
  return sxSort('Sort the substances: do they <b>dissolve</b> in water?',[['yes','Dissolves'],['no','Does not dissolve']],it,'If it seems to disappear and spreads evenly, it dissolved.','Sugar, salt and drink powder dissolve; sand, pebbles, oil and chalk do not.')}},
 {tag:'props',f(){const mats={iron:['gray','yes','yes','no'],copper:['orange-brown','no','yes','no'],plastic:['any color','no','no','no'],salt:['white','no','no','yes']},name=pick(Object.keys(mats)),p=mats[name];
  return {prompt:`A mystery material has these properties. What is it most likely?`,visual:sxTable(['Property','Mystery material'],[['Color',p[0]],['Attracted to a magnet?',p[1]],['Conducts electricity?',p[2]],['Dissolves in water?',p[3]]]),...strChoices(name,Object.keys(mats).filter(x=>x!==name)),hint:`Check every property, not just the color.`,explain:`Only <b>${name}</b> matches all four properties.`}}},
 {tag:'mixing',f(){const C=[['burning a candle','c'],['baking a cake','c'],['an iron nail rusting','c'],['vinegar and baking soda fizzing','c'],['cutting paper','p'],['melting ice','p'],['mixing sand and salt','p'],['dissolving sugar in tea','p']],it=sxPick(C.slice(0,4),3).concat(sxPick(C.slice(4),3));
  return sxSort('Sort the changes: did a <b>new substance</b> form?',[['c','New substance forms'],['p','No new substance']],it,'Look for signs like bubbles of gas, a new color, light, heat or a new smell.','Burning, baking, rusting and fizzing make new substances; cutting, melting, mixing and dissolving do not.')}},
 {tag:'mixing',f(){const M=pick([['iron filings and sand','a magnet'],['salt water','letting the water evaporate'],['pebbles and sand','a sieve (screen)'],['sand and water','a filter'],['marbles and rice','picking them out by hand']]);
  return {prompt:`What is the best way to separate <b>${M[0]}</b>?`,...strChoices(M[1],['a magnet','letting the water evaporate','a sieve (screen)','a filter','picking them out by hand'].filter(x=>x!==M[1])),long:true,hint:`Use a property that is different for the two parts.`,explain:`Use <b>${M[1]}</b> to separate ${M[0]}.`}}},
 {tag:'gravity',f(){const where=pick(['at the North Pole','in Brazil','in Australia','in California','on a ship in the ocean']);
  return {prompt:`A ball is dropped <b>${where}</b>. Which way does gravity pull it?`,visual:`<svg viewBox="0 0 200 200" style="width:200px" role="img" aria-label="Earth"><circle cx="100" cy="100" r="70" fill="#5fc3f0" stroke="#1f3557" stroke-width="3"/><path d="M58 70 q20-28 50-18 t30 6 q-6 18-34 14 t-46-2z" fill="#8fd46a"/><circle cx="100" cy="100" r="4" fill="#1f3557"/><text x="108" y="104" ${FONT} font-size="12" fill="#1f3557">center</text></svg>`,...strChoices('toward the center of Earth',['toward the North Pole','away from Earth','toward the sun']),hint:`Gravity pulls everything toward Earth's center, wherever you are.`,explain:`Everywhere on Earth, "down" means <b>toward Earth's center</b>.`}}},
 {tag:'energyfood',f(){const C=pick([['the sun','grass','a rabbit','a fox'],['the sun','algae','a small fish','a heron'],['the sun','a corn plant','a mouse','a snake'],['the sun','an oak tree (acorns)','a squirrel','a hawk']]);
  return {kind:'order',items:C,prompt:`Put the path of <b>energy</b> in order, from where it starts.`,hint:`Energy starts as sunlight. Plants capture it first.`,explain:`${C.join(' → ')}. The energy in every animal's food first came from the sun.`}}},
 {tag:'plantsair',f(){const soil=R(90,100)*1000,loss=R(50,120),gain=R(30,75)*1000;
  return {prompt:`A scientist grew a small willow tree in a pot for 5 years, adding only water. What does the data suggest?`,visual:sxTable(['','At the start','After 5 years'],[['Tree',`${fmt(R(2,3)*1000)} g`,`${fmt(gain)} g`],['Soil',`${fmt(soil)} g`,`${fmt(soil-loss)} g`]]),...strChoices('Most of the tree\'s new mass did not come from the soil; it came mostly from air and water.',['All of the tree\'s mass came from the soil.','The soil grew too.','Trees do not gain mass.']),long:true,hint:`How much did the soil lose compared to how much the tree gained?`,explain:`The soil lost only ${loss} g, but the tree gained thousands of grams: plant matter comes mostly from <b>air (carbon dioxide) and water</b>.`}}},
 {tag:'plantsair',f(){const L=R(18,30),D=R(2,6);
  return {prompt:`Two identical plants got the same water. One was kept in light, the other in the dark. Why did the plant in light grow more?`,visual:sciBars(['Light','Dark'],[L,D],'Growth in 2 weeks (cm)','Where it was kept','#38b98a'),...strChoices('Plants use light energy to make food from air and water.',['Darkness is too cold.','Light makes the soil warmer.','The dark plant was a different kind.']),long:true,hint:`What do plants need light for?`,explain:`Plants use <b>light energy</b> to make sugar from carbon dioxide and water.`}}},
 {tag:'foodweb',f(){const C=pick([['grass','grasshopper','frog','snake','hawk'],['algae','tadpole','fish','heron'],['seeds','mouse','owl'],['leaves','caterpillar','bird','cat']]);
  return {kind:'order',items:C,prompt:`Put the <b>food chain</b> in order, starting with the producer.`,hint:`The producer makes its own food. Each next one eats the one before it.`,explain:`${C.join(' → ')}.`}}},
 {tag:'foodweb',f(){const W=pick([['rabbits','foxes','grass','Foxes would have less food and might decrease; grass might grow more.'],['frogs','snakes','insects','Snakes would have less food; insects might increase.'],['mice','owls','seeds','Owls would have less food; more seeds might be left to grow.']]);
  return {prompt:`In a food web, ${W[1]} eat ${W[0]}, and ${W[0]} eat ${W[2]}. What would most likely happen if the <b>${W[0]}</b> disappeared?`,...strChoices(W[3],[`Nothing would change.`,`The ${W[1]} would have more food.`,`The ${W[2]} would disappear too.`]),long:true,hint:`Think about who eats ${W[0]} and who ${W[0]} eat.`,explain:`<b>${W[3]}</b> Every part of a food web is connected.`}}},
 {tag:'foodweb',f(){const O=[['oak tree','p'],['grass','p'],['algae','p'],['deer','c'],['hawk','c'],['caterpillar','c'],['mushroom','d'],['earthworm','d'],['bacteria','d']],it=['p','c','d'].flatMap(b=>sxPick(O.filter(x=>x[1]===b),2));
  return sxSort('Sort the living things in a food web.',[['p','Producer'],['c','Consumer'],['d','Decomposer']],it,'Producers make food from sunlight. Consumers eat other living things. Decomposers break down dead things.','Producers: plants and algae. Consumers: animals. Decomposers: fungi, worms, bacteria.')}},
 {tag:'stars',f(){const S=[['Star A',R(5,10)],['Star B',R(40,60)],['Star C',R(100,200)]];
  return {prompt:`Three stars give off the <b>same</b> amount of light. Their distances from Earth are in the table. Which looks <b>brightest</b> from Earth?`,visual:sxTable(['Star','Distance (light-years)'],S.map(x=>[x[0],x[1]])),...strChoices('Star A',['Star B','Star C','They look the same']),hint:`Things look brighter when they are closer.`,explain:`Star A is closest (${S[0][1]} light-years), so it looks <b>brightest</b>.`}}},
 {tag:'patterns',f(){const T=['8 AM','10 AM','Noon','2 PM','4 PM'],mid=R(20,40),vals=[mid+R(80,110),mid+R(30,45),mid,mid+R(30,45),mid+R(80,110)],k=coin();
  return k?{prompt:`Pip measured a flagpole's shadow during the day. When was the shadow <b>shortest</b>?`,visual:sciBars(T,vals,'Shadow length (cm)','Time','#7b6cf0'),...strChoices('Noon',T.filter(x=>x!=='Noon')),hint:`Find the shortest bar.`,explain:`The shadow is shortest at <b>noon</b>, when the sun is highest in the sky.`}
   :{prompt:`Why does the shadow change length during the day?`,visual:sciBars(T,vals,'Shadow length (cm)','Time','#7b6cf0'),...strChoices('Earth rotates, so the sun appears in a different place in the sky.',['The flagpole grows.','The sun gets bigger at noon.','Clouds make shadows longer.']),long:true,hint:`Is the sun moving, or is Earth?`,explain:`<b>Earth's rotation</b> changes where the sun appears, which changes the shadow.`}}},
 {tag:'patterns',f(){const M=['Jan','Mar','May','Jun','Aug','Oct','Dec'],base=[9.8,11.9,14.0,14.6,13.6,11.0,9.5].map(x=>Math.round((x+R(-3,3)/10)*10)/10),k=coin(),mx=M[base.indexOf(Math.max(...base))];
  return {prompt:k?`The graph shows hours of daylight in a California town. Which month has the <b>longest</b> days?`:`Why are days longer in summer than in winter?`,visual:sciBars(M,base,'Hours of daylight','Month','#ffc23d'),...(k?strChoices(mx,M):strChoices('Earth is tilted, so in summer our part of Earth leans toward the sun.',['The sun is closer to Earth in summer.','Earth spins faster in winter.','The moon blocks the sun in winter.'])),long:!k,hint:k?`Find the tallest bar.`:`Think about Earth's tilt as it orbits the sun.`,explain:k?`<b>${mx}</b> has the most daylight.`:`Because of <b>Earth's tilt</b>, summer days are longer.`}}},
 {tag:'spheres',f(){const S=[['mountains','g'],['sand','g'],['volcano lava','g'],['rivers','h'],['glaciers','h'],['oceans','h'],['wind','a'],['oxygen in the air','a'],['carbon dioxide','a'],['trees','b'],['whales','b'],['mushrooms','b']],it=['g','h','a','b'].flatMap(b=>sxPick(S.filter(x=>x[1]===b),b==='g'||b==='b'?2:1));
  return sxSort('Sort each part of Earth into its <b>sphere</b>.',[['g','Geosphere (rock)'],['h','Hydrosphere (water)'],['a','Atmosphere (air)'],['b','Biosphere (life)']],it,'Geo = rock, hydro = water, atmo = air, bio = life.','Each part of Earth belongs to one of the four spheres.')}},
 {tag:'water',f(){const k=coin();
  return {prompt:k?`The table shows where Earth's water is. Where is <b>most</b> of it?`:`What is <b>most</b> of Earth's <b>fresh</b> water?`,visual:sxTable(['Where the water is','Percent of all Earth\'s water'],[['Oceans (salt water)','about 97%'],['Ice and glaciers (fresh)','about 2%'],['Groundwater (fresh)','less than 1%'],['Lakes and rivers (fresh)','much less than 1%']]),...(k?strChoices('in the oceans',['in ice and glaciers','in lakes and rivers','in groundwater']):strChoices('frozen in ice and glaciers',['in lakes and rivers','in the oceans','in clouds'])),hint:k?`Find the tallest bar.`:`Ocean water is salty. Of the rest, which is biggest?`,explain:k?`About 97% is in the <b>oceans</b>.`:`Most fresh water is <b>frozen in ice and glaciers</b>; lakes and rivers hold very little.`}}},
 {tag:'protect',f(){const A=[['recycling cans','h'],['planting trees','h'],['using a reusable water bottle','h'],['turning off lights','h'],['dumping oil down a drain','x'],['leaving the car running','x'],['littering at the beach','x'],['wasting water','x']],it=sxPick(A.slice(0,4),3).concat(sxPick(A.slice(4),3));
  return sxSort('Sort the actions: do they <b>help</b> or <b>harm</b> Earth\'s resources?',[['h','Helps'],['x','Harms']],it,'Think about air, water, land and living things.','Reducing waste and pollution protects Earth; dumping, littering and wasting harm it.')}},
 {tag:'design5',f(){const D=['Filter A','Filter B','Filter C'];let clear,time;do{clear=D.map(()=>R(4,10));time=D.map(()=>R(2,12))}while(new Set(clear).size<3);const best=D[clear.indexOf(Math.max(...clear))];
  return {prompt:`Engineers tested three water filters. The goal is the <b>cleanest</b> water. Which filter best meets the goal?`,visual:sxTable(['','Clearness (1-10)','Time (minutes)'],D.map((d,i)=>[d,clear[i],time[i]])),...strChoices(best,D),hint:`The goal is clean water, not speed.`,explain:`<b>${best}</b> made the clearest water (${Math.max(...clear)} out of 10).`}}},
 {tag:'design5',f(){const E=pick([['which insulation keeps a drink coldest','the starting temperature of the drink','the insulation material'],['which solar oven gets hottest','how long each oven sits in the sun','the color of the oven lining'],['which shape boat holds the most pennies','the size of the foil sheet','the boat shape'],['which parachute falls slowest','the weight that hangs from it','the parachute size']]);
  return {prompt:`Engineers test <b>${E[0]}</b>. What must stay the <b>same</b> for a fair test?`,...strChoices(E[1],[E[2],'the result they want','nothing']),hint:`Only the thing being tested should change.`,explain:`They change ${E[2]}, so <b>${E[1]}</b> must stay the same.`}}}
];
